import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { SAMPLE_VIDEO } from '../data';
import './AuthForms.css';

export default function Signup({ onSignup }) {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    name: '',
    age: '',
    email: '',
    password: '',
  });
  const [role, setRole] = useState('student');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleChange = (e) =>
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (role === 'student' && !form.age) {
      return setError('Please enter your age for student signup.');
    }
    if (role === 'staff' && form.age) {
      return setError('Staff signup should not include age.');
    }

    try {
      const res = await fetch('http://localhost:5000/api/auth/signup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: form.name,
          email: form.email,
          password: form.password,
          role,
          ...(role === 'student' && { age: form.age }),
        }),
      });

      const data = await res.json();
      if (res.ok && data.user) {
        localStorage.setItem('token', data.token || '');
        localStorage.setItem('user', JSON.stringify(data.user));
        localStorage.setItem('role', role);
        setSuccess('Account created successfully!');
        onSignup(data.user);
        setTimeout(() => {
          navigate(role === 'staff' ? '/staff-dashboard' : '/dashboard');
        }, 800);
      } else setError(data.message || 'Failed to create account.');
    } catch (err) {
      setError('Something went wrong. Please try again.');
    }
  };

  const bgColor = role === 'student' ? '#e3f2fd' : '#e8f5e9';
  const themeColor = role === 'student' ? '#1976d2' : '#2e7d32';

  return (
    <div
      className="auth-page"
      style={{
        background: bgColor,
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        transition: 'background 0.3s ease',
      }}
    >
      <div className="video-bg" aria-hidden>
        <video autoPlay muted loop playsInline>
          <source src={SAMPLE_VIDEO} type="video/mp4" />
        </video>
        <div className="overlay" />
      </div>

      <div
        className="auth-card"
        style={{
          background: 'white',
          borderRadius: '16px',
          padding: '40px 50px',
          boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
          width: '400px',
          position: 'relative',
          zIndex: 1,
          textAlign: 'center',
        }}
      >
        <h1 style={{ color: themeColor, marginBottom: '10px' }}>
          Welcome to NEXORA
        </h1>
        <p style={{ color: '#555', marginBottom: '20px' }}>
          Create your {role} account
        </p>

        <div
          style={{
            display: 'flex',
            justifyContent: 'center',
            gap: '12px',
            marginBottom: '25px',
          }}
        >
          <button
            type="button"
            onClick={() => setRole('student')}
            style={{
              background: role === 'student' ? themeColor : '#ccc',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              padding: '8px 18px',
              cursor: 'pointer',
              fontWeight: 600,
            }}
          >
            Student
          </button>
          <button
            type="button"
            onClick={() => setRole('staff')}
            style={{
              background: role === 'staff' ? themeColor : '#ccc',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              padding: '8px 18px',
              cursor: 'pointer',
              fontWeight: 600,
            }}
          >
            Staff
          </button>
        </div>

        <form
          className="form"
          onSubmit={handleSubmit}
          style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}
        >
          <input
            className="input"
            name="name"
            placeholder={role === 'student' ? 'Student Name' : 'Staff Name'}
            value={form.name}
            onChange={handleChange}
            required
          />
          <input
            className="input"
            name="email"
            type="email"
            placeholder={
              role === 'student' ? 'student@school.edu' : 'staff@school.edu'
            }
            value={form.email}
            onChange={handleChange}
            required
          />
          {role === 'student' && (
            <input
              className="input"
              name="age"
              type="number"
              placeholder="Age"
              value={form.age}
              onChange={handleChange}
              required
            />
          )}
          <input
            className="input"
            name="password"
            type="password"
            placeholder="Password"
            value={form.password}
            onChange={handleChange}
            required
          />
          <button
            className="btn btn-primary"
            type="submit"
            style={{
              background: themeColor,
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              padding: '10px',
              marginTop: '10px',
              cursor: 'pointer',
            }}
          >
            Sign Up
          </button>
          {error && <p style={{ color: 'red', marginTop: '8px' }}>{error}</p>}
          {success && (
            <p style={{ color: 'green', marginTop: '8px' }}>{success}</p>
          )}
        </form>
      </div>
    </div>
  );
}
